(()=>{'use strict';
const M=window.matclubLabModels,host=document.getElementById('labSection');if(!M||!host)return;
const $=s=>host.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n===null||!Number.isFinite(n)?'—':n===0?'0':Math.abs(n)<.001||Math.abs(n)>=1e6?n.toExponential(3):Number(n.toPrecision(5)).toLocaleString('ru-RU',{maximumFractionDigits:5});
const key='matclub-laboratory-v1';let saved={};try{const raw=JSON.parse(localStorage.getItem(key));if(raw&&typeof raw==='object'&&!Array.isArray(raw))saved=raw}catch{}
let current=M.labs.find(e=>e.id===saved.selected)||M.labs[0],params=M.defaults(current),time=0,playing=false,frame=0,last=0,previousPaint=0,mounted=false,baseline=null,plot=null,filter='all',search='',grade='all';
let journal={},notes={},settings={};
for(const e of M.labs){const raw=saved.journal?.[e.id];journal[e.id]=Array.isArray(raw)?raw.slice(-120).filter(x=>x&&typeof x==='object'&&Number.isFinite(x.time)&&x.params&&typeof x.params==='object').map(x=>({params:M.normalize(e,x.params),time:Math.max(0,Math.min(x.time,e.duration?e.duration(M.normalize(e,x.params)):0))})):[];notes[e.id]={hypothesis:String(saved.notes?.[e.id]?.hypothesis||'').slice(0,4000),conclusion:String(saved.notes?.[e.id]?.conclusion||'').slice(0,4000)};settings[e.id]=M.normalize(e,saved.settings?.[e.id]);}
params=settings[current.id];
function status(s){const el=$('#labStatus');if(el)el.textContent=s}
function save(){try{localStorage.setItem(key,JSON.stringify({selected:current.id,journal,notes,settings}));return true}catch{status('Записи доступны сейчас, но браузер не разрешил сохранение. Скачай CSV, чтобы сохранить измерения.');return false}}
function updateLink(){const url=new URL(location.href);url.searchParams.delete('python');url.searchParams.delete('topic');url.searchParams.set('lab',current.id);history.replaceState(null,'',url.pathname+url.search+url.hash)}
function catalogue(){const selected=M.labs.filter(e=>(filter==='all'||e.group===filter)&&(grade==='all'||e.grade.split('–').map(Number).some((_,i,a)=>Number(grade)>=a[0]&&Number(grade)<=a[a.length-1]))&&(`${e.title} ${e.intro} ${e.group}`).toLowerCase().includes(search));$('#labCount').textContent=`Найдено: ${selected.length} из ${M.labs.length}`;$('#labExperiments').innerHTML=selected.length?selected.map(e=>`<button class="lab-card" data-lab-open="${e.id}" aria-pressed="${current.id===e.id}"><span class="lab-card-icon" aria-hidden="true">${e.symbol}</span><span class="lab-card-info"><small>${e.group} · ${e.grade} кл.</small><b>${e.title}</b></span><span aria-hidden="true">↗</span></button>`).join(''):'<p class="lab-empty">Ничего не найдено. Измени запрос или выбери все разделы.</p>';}
function mount(){mounted=true;host.innerHTML=`<div class="lab-heading"><div><div class="eyebrow">МАТКЛУБ / ФИЗИЧЕСКАЯ ЛАБОРАТОРИЯ</div><h1 id="labTitle">Поставь опыт.<br><em>Открой закономерность.</em></h1><p>Меняй условия. Измеряй. Проверяй гипотезы.</p></div><div class="lab-heading-mark" aria-hidden="true"><span>20</span><small>ОПЫТОВ<br>7–11 КЛАССЫ</small></div></div><details class="lab-catalog" open><summary><span>Выбрать опыт</span><span id="labCount"></span></summary><div class="lab-filters"><label>Поиск<input id="labSearch" type="search" placeholder="Линза, маятник, ток…"></label><label>Направление<select id="labGroup"><option value="all">Все направления</option>${[...new Set(M.labs.map(e=>e.group))].map(g=>`<option>${g}</option>`).join('')}</select></label><label>Класс<select id="labGrade"><option value="all">Все классы</option>${[7,8,9,10,11].map(g=>`<option>${g}</option>`).join('')}</select></label></div><div id="labExperiments" class="lab-experiments"></div></details><div id="labWorkspace" class="lab-workspace" tabindex="-1"></div><p id="labStatus" class="lab-status" role="status"></p><p class="lab-local">Модели работают на устройстве без входа в аккаунт. Параметры, гипотезы и журнал сохраняются в этом браузере. <a href="/laboratory/">Справочник опытов →</a></p>`;catalogue();workspace();}
function workspace(){const e=current,d=M.domain(e,params);$('#labWorkspace').innerHTML=`<div class="lab-work-head"><div><span class="lab-kicker">${e.group.toUpperCase()} / ${e.grade} КЛАСС</span><h2 id="labExperimentTitle">${e.title}</h2><p>${e.intro}</p></div><button id="labCopyLink" class="lab-btn">Ссылка на опыт ↗</button></div><div class="lab-grid"><aside class="lab-controls"><div class="lab-block-head"><h3>Условия опыта</h3><button id="labReset" class="lab-text-btn">Сбросить</button></div><div class="lab-presets">${e.presets.map((x,i)=>`<button data-lab-preset="${i}">${x[0]}</button>`).join('')}</div>${e.params.map(q=>q.options?`<label class="lab-control">${q.label}<select data-lab-param="${q.key}" aria-label="${q.label}">${q.options.map(o=>`<option value="${o[0]}" ${params[q.key]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label>`:`<div class="lab-control"><label for="lab-${q.key}">${q.label} <small>${q.unit}</small></label><div class="lab-number-row"><input id="lab-${q.key}" type="number" data-lab-param="${q.key}" min="${q.min}" max="${q.max}" step="${q.step}" value="${params[q.key]}" inputmode="decimal"><span>${q.unit}</span></div><input type="range" data-lab-range="${q.key}" min="${q.min}" max="${q.max}" step="${q.step}" value="${params[q.key]}" aria-label="${q.label}, ползунок"><div class="lab-range-labels"><span>${q.min}</span><span>${q.max}</span></div></div>`).join('')}<p class="lab-control-note">Параметры меняют расчёт сразу. ${e.sweep?'График показывает зависимость при изменении одного параметра.':'Изменение условий возвращает время к началу.'}</p></aside><div class="lab-observation"><div class="lab-apparatus"><div class="lab-stage-head"><span><i></i> ВИРТУАЛЬНАЯ УСТАНОВКА</span><span>${e.sweep?'СТАТИЧЕСКИЙ ОПЫТ':'ДИНАМИЧЕСКИЙ ОПЫТ'}</span></div><div id="labScene" class="lab-scene"></div><div class="lab-stage-foot" id="labSceneCaption"></div></div><div class="lab-transport" ${e.sweep?'hidden':''}><div class="lab-play-row"><button id="labPlay" class="lab-btn lab-primary" aria-pressed="false">▶ Запустить</button><button id="labStep" class="lab-btn" title="Шаг на одну сотую длительности опыта">Шаг +</button><button id="labRestart" class="lab-btn" aria-label="Вернуть время к нулю">↺</button><label>Скорость<select id="labSpeed"><option value="0.5">0,5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label></div><label class="lab-time-label" for="labTime">Время модели <output id="labTimeText"></output></label><input id="labTime" type="range" min="0" max="1000" step="1" value="0" aria-label="Время модели"><p>Один проход шкалы ≈ 12 секунд при 1×. Физическое время указано выше.</p></div><div class="lab-metrics">${e.metrics.map(m=>`<div><span>${m.label}</span><strong data-lab-value="${m.key}">—</strong><small>${m.unit||'без единицы'}</small></div>`).join('')}</div><div class="lab-chart-card"><div class="lab-block-head"><h3>График зависимости</h3><button id="labDownloadPlot" class="lab-text-btn">↓ SVG</button></div><div class="lab-chart-legend"><span><i></i>Текущие условия</span><span id="labBaselineLegend" hidden><i></i>Закреплённые условия</span></div><div id="labChart" class="lab-chart"></div><div class="lab-compare"><button id="labPin" class="lab-btn">＋ Закрепить для сравнения</button><button id="labUnpin" class="lab-text-btn" hidden>Убрать сравнение</button></div><p id="labBaselineDescription" class="lab-control-note"></p><p class="lab-control-note">Точка — текущее состояние. ${e.id==='lens'?'Разрыв при d = F — изображение на бесконечности.':e.id==='refraction'?'В области полного отражения угол преломления не определён.':'Шкала графика подстраивается под диапазон значений.'}</p></div></div></div><div class="lab-research-grid"><section class="lab-theory"><span class="lab-kicker">01 / ПОЙМИ МОДЕЛЬ</span><h3>Физика за наблюдением</h3><p class="lab-formula">${e.formula}</p><p>${e.explain}</p><details><summary>Допущения и границы модели</summary><p>${e.limits}</p></details><h4>Проведи исследование</h4><ol>${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><section class="lab-notebook"><span class="lab-kicker">02 / ПРОВЕРЬ ГИПОТЕЗУ</span><h3>Твой лабораторный журнал</h3><label for="labHypothesis">Что изменится и почему?</label><textarea id="labHypothesis" maxlength="4000" rows="3" placeholder="Предполагаю, что при увеличении…">${esc(notes[e.id].hypothesis)}</textarea><div class="lab-record-row"><button id="labRecord" class="lab-btn lab-primary">＋ Записать измерение</button><button id="labExport" class="lab-btn">↓ CSV</button></div><div id="labMeasurements"></div><label for="labConclusion">Вывод по результатам опыта</label><textarea id="labConclusion" maxlength="4000" rows="3" placeholder="Моя гипотеза… Это подтверждают измерения…">${esc(notes[e.id].conclusion)}</textarea><small>До 120 измерений на опыт. В CSV входят условия, показания и твои заметки.</small></section></div><section class="lab-challenge"><div><span class="lab-kicker">03 / РАССЧИТАЙ САМОСТОЯТЕЛЬНО</span><h3>Проверь понимание</h3><p>${e.question}</p><small>Задача использует текущие условия опыта. Допуск — 1% или 0,01 для очень малых значений.</small></div><form id="labAnswerForm"><label for="labAnswer">Твой числовой ответ</label><div><input id="labAnswer" type="text" inputmode="decimal" autocomplete="off" placeholder="Например, 12,5" required><button class="lab-btn lab-primary" type="submit">Проверить</button></div><p id="labAnswerResult" role="status"></p><details><summary>Разбор решения</summary><p>${e.solution}</p><p id="labAnswerSolution"></p></details></form></section>`;
graph();paint();table();}
function values(p=params,t=time){return current.calc(p,t)}
function paint(){if(!mounted)return;const r=values();$('#labScene').innerHTML=window.matclubLabScenes.draw(current,params,time,r);for(const m of current.metrics)$(`[data-lab-value="${m.key}"]`).textContent=fmt(r[m.key]);const d=M.domain(current,params);if(!current.sweep){$('#labTime').value=time/d.max*1000;$('#labTimeText').textContent=`${fmt(time)} / ${fmt(d.max)} ${d.unit}`;}$('#labSceneCaption').textContent=current.id==='refraction'?(r.tir?'Полное отражение: преломлённого луча нет.':'Углы отсчитываются от нормали к границе.'):current.id==='lens'?(r.q===null?'Изображение на бесконечности.':r.q<0?'Пунктир — продолжения лучей, изображение мнимое.':'Сплошные лучи пересекаются в действительном изображении.'):current.id==='photoelectric'?(r.emits?'Энергии фотона хватает для фотоэмиссии.':'Энергии фотона недостаточно для вылета с ненулевой скоростью.'):current.sweep?'Меняй условия и записывай показания.':playing?'Опыт идёт · можно поставить на паузу в любой момент.':'Изучай состояние по шкале времени или запусти опыт.';
if(plot){const x=current.sweep?params[current.sweep]:time,y=r[current.graph.key],point=$('#labPlotPoint');if(point){point.hidden=!Number.isFinite(y);point.setAttribute('visibility',Number.isFinite(y)?'visible':'hidden');if(Number.isFinite(y)){point.setAttribute('cx',plot.x(x));point.setAttribute('cy',plot.y(y))}}}
$('#labAnswerSolution').textContent=`При текущих условиях: ${fmt(current.answer(params,r))}.`;
}
function graph(){const e=current,d=M.domain(e,params),db=baseline?M.domain(e,baseline):d,min=Math.min(d.min,db.min),max=Math.max(d.max,db.max),series=p=>{const range=M.domain(e,p);return Array.from({length:301},(_,i)=>{const x=range.min+(range.max-range.min)*i/300;return{x,y:M.sample(e,p,x)[e.graph.key]}})};const main=series(params),prev=baseline?series(baseline):[],ys=[...main,...prev].map(a=>a.y).filter(Number.isFinite);let lo=Math.min(0,...ys),hi=Math.max(0,...ys);if(hi-lo<1e-9){hi=lo+1}const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const x=v=>65+(v-min)/(max-min)*500,y=v=>235-(v-lo)/(hi-lo)*190;plot={x,y};const curve=(s,p)=>{let pen=false,oldX=null;const cut=e.graph.breakAt?.(p);return s.map(a=>{if(!Number.isFinite(a.y)){pen=false;oldX=a.x;return''}const crosses=cut!==undefined&&oldX!==null&&oldX<cut&&a.x>cut;const segment=`${pen&&!crosses?'L':'M'}${x(a.x).toFixed(2)} ${y(a.y).toFixed(2)}`;pen=true;oldX=a.x;return segment}).join(' ')};
let grid='';for(let i=0;i<=4;i++){const xv=min+(max-min)*i/4,yv=lo+(hi-lo)*i/4;grid+=`<path d="M${x(xv)} 45V235M65 ${y(yv)}H565" stroke="#dde4df" stroke-width="1"/><text x="${x(xv)}" y="257" text-anchor="middle">${esc(fmt(xv))}</text><text x="56" y="${y(yv)+4}" text-anchor="end">${esc(fmt(yv))}</text>`}
$('#labChart').innerHTML=`<svg id="labPlotSvg" viewBox="0 0 600 300" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(e.graph.label)} от ${esc(d.label)}"><title>${esc(e.title)}: ${esc(e.graph.label)} от ${esc(d.label)}</title><desc>Зелёная линия — текущие условия.${baseline?' Пунктирная оранжевая — закреплённые условия.':''} Числа доступны также в приборных показаниях и журнале.</desc><rect width="600" height="300" fill="#fbfcfa"/><g fill="#476056" font-family="system-ui,sans-serif" font-size="11">${grid}<text x="65" y="23">${esc(e.graph.label)}${e.graph.unit?', '+e.graph.unit:''}</text><text x="565" y="287" text-anchor="end">${esc(d.label)}${d.unit?', '+d.unit:''}</text></g>${baseline?`<path d="${curve(prev,baseline)}" fill="none" stroke="#a86631" stroke-width="2.5" stroke-dasharray="7 5"/>`:''}<path d="${curve(main,params)}" fill="none" stroke="#2b725c" stroke-width="3"/><circle id="labPlotPoint" r="5" fill="#163e31" stroke="white" stroke-width="2"/></svg>`;$('#labBaselineLegend').hidden=!baseline;$('#labUnpin').hidden=!baseline;$('#labBaselineDescription').textContent=baseline?'Сравнение: '+parameterText(baseline):'';}
function parameterText(p){return current.params.map(q=>`${q.label}: ${q.options?q.options.find(o=>o[0]===p[q.key])?.[1]:fmt(p[q.key])}${q.unit?' '+q.unit:''}`).join(' · ')}
function table(){const rows=journal[current.id],e=current;$('#labMeasurements').innerHTML=rows.length?`<div class="lab-table-scroll" tabindex="0" role="region" aria-label="Таблица измерений"><table><caption>${rows.length} / 120 измерений</caption><thead><tr><th scope="col">№</th><th scope="col">Условия</th>${e.sweep?'':`<th scope="col">t, ${e.timeUnit||'с'}</th>`}${e.metrics.map(m=>`<th scope="col">${m.label}${m.unit?', '+m.unit:''}</th>`).join('')}<th scope="col">Удалить</th></tr></thead><tbody>${rows.map((row,i)=>{const r=e.calc(row.params,row.time);return`<tr><td>${i+1}</td><td><details><summary>Параметры</summary><p>${esc(parameterText(row.params))}</p></details></td>${e.sweep?'':`<td>${fmt(row.time)}</td>`}${e.metrics.map(m=>`<td>${fmt(r[m.key])}</td>`).join('')}<td><button data-lab-delete="${i}" aria-label="Удалить измерение ${i+1}">×</button></td></tr>`}).join('')}</tbody></table></div>`:'<p class="lab-empty">Пока нет измерений. Выбери условия и нажми «Записать измерение».</p>';$('#labExport').disabled=!rows.length;$('#labRecord').disabled=rows.length>=120;}
function stop(){playing=false;cancelAnimationFrame(frame);frame=0;const b=$('#labPlay');if(b){b.textContent='▶ Запустить';b.setAttribute('aria-pressed','false')}}
function tick(now){if(!playing||host.hidden||document.hidden){stop();return}const duration=current.duration(params),elapsed=last?Math.min((now-last)/1000,.1):0;last=now;time=Math.min(duration,time+elapsed*duration/12*Number($('#labSpeed').value));if(now-previousPaint>=32||time>=duration){paint();previousPaint=now}if(time>=duration){stop();paint();status('Опыт завершён. Можно записать результат или начать заново.');return}frame=requestAnimationFrame(tick)}
function play(){if(playing){stop();paint();return}if(time>=current.duration(params))time=0;playing=true;last=0;$('#labPlay').textContent='Ⅱ Пауза';$('#labPlay').setAttribute('aria-pressed','true');frame=requestAnimationFrame(tick)}
function changeParameter(q,value){if(!Number.isFinite(value))return;stop();params=M.normalize(current,{...params,[q.key]:value});settings[current.id]=params;time=0;const number=$(`[data-lab-param="${q.key}"]`),range=$(`[data-lab-range="${q.key}"]`);number.value=params[q.key];number.setCustomValidity('');if(range)range.value=params[q.key];$('#labAnswerResult').textContent='';graph();paint();save();}
function open(id,focus=false){const e=M.labs.find(e=>e.id===id);if(!e)return;stop();current=e;params=settings[e.id];time=0;baseline=null;if(!mounted)mount();else{catalogue();workspace()}updateLink();save();if(focus){$('#labWorkspace').focus({preventScroll:true});$('#labWorkspace').scrollIntoView({block:'start',behavior:'auto'});if(innerWidth<768)$('.lab-catalog').open=false}status('Опыт «'+e.title+'» готов.');}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const e=current,quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"',rows=[['Матклуб / '+e.title],['Гипотеза',notes[e.id].hypothesis],['Вывод',notes[e.id].conclusion],['№',...e.params.map(q=>q.label+(q.unit?', '+q.unit:'')),...(e.sweep?[]:['Время, '+(e.timeUnit||'с')]),...e.metrics.map(q=>q.label+(q.unit?', '+q.unit:''))]];journal[e.id].forEach((row,i)=>{const r=e.calc(row.params,row.time);rows.push([i+1,...e.params.map(q=>q.options?q.options.find(o=>o[0]===row.params[q.key])?.[1]:row.params[q.key]),...(e.sweep?[]:[row.time]),...e.metrics.map(q=>r[q.key]===null?'не определено':r[q.key])])});return'\ufeff'+rows.map(row=>row.map(v=>quote(typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v)).join(';')).join('\r\n')}
host.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.labOpen){open(b.dataset.labOpen,true);return}if(b.dataset.labPreset!==undefined){stop();params=M.normalize(current,{...params,...current.presets[+b.dataset.labPreset][1]});settings[current.id]=params;time=0;workspace();save();status('Набор условий применён.');return}if(b.dataset.labDelete!==undefined){journal[current.id].splice(+b.dataset.labDelete,1);table();save();return}
switch(b.id){case'labPlay':play();break;case'labStep':stop();time=Math.min(current.duration(params),time+current.duration(params)/100);paint();break;case'labRestart':stop();time=0;paint();break;case'labReset':stop();params=M.defaults(current);settings[current.id]=params;time=0;baseline=null;workspace();save();status('Условия сброшены. Журнал и заметки сохранены.');break;case'labPin':baseline={...params};graph();paint();status('График закреплён. Измени условия и сравни линии.');break;case'labUnpin':baseline=null;graph();paint();break;case'labRecord':if(journal[current.id].length<120){journal[current.id].push({params:{...params},time});table();if(save())status('Измерение записано и сохранено в этом браузере.')}break;case'labExport':download(csv(),`matclub-${current.id}-measurements.csv`,'text/csv;charset=utf-8');break;case'labDownloadPlot':download(new XMLSerializer().serializeToString($('#labPlotSvg')),`matclub-${current.id}-graph.svg`,'image/svg+xml');break;case'labCopyLink':updateLink();try{await navigator.clipboard.writeText(location.href);status('Ссылка на опыт скопирована.')}catch{status('Ссылка на опыт: '+location.href)}break;}
});
host.addEventListener('input',event=>{const el=event.target;if(el.dataset.labRange){const q=current.params.find(q=>q.key===el.dataset.labRange);changeParameter(q,Number(el.value));return}if(el.id==='labTime'){stop();time=current.duration(params)*Number(el.value)/1000;paint()}if(el.id==='labSearch'){search=el.value.toLowerCase().trim();catalogue()}if(el.id==='labHypothesis'||el.id==='labConclusion'){notes[current.id][el.id==='labHypothesis'?'hypothesis':'conclusion']=el.value.slice(0,4000);save()}});
host.addEventListener('change',event=>{const el=event.target;if(el.dataset.labParam){const q=current.params.find(q=>q.key===el.dataset.labParam),n=Number(el.value);if(el.value.trim()===''||!Number.isFinite(n)){el.setCustomValidity('Введи конечное число.');el.reportValidity();return}changeParameter(q,n)}if(el.id==='labGroup'){filter=el.value;catalogue()}if(el.id==='labGrade'){grade=el.value;catalogue()}});
host.addEventListener('submit',event=>{if(event.target.id!=='labAnswerForm')return;event.preventDefault();const input=$('#labAnswer').value.trim().replace(/\s/g,'').replace(',','.'),n=Number(input),answer=current.answer(params,values()),out=$('#labAnswerResult');if(!input||!Number.isFinite(n)){out.textContent='Введи число, например 12,5 или 1.2e3.';return}const ok=Math.abs(n-answer)<=Math.max(.01,Math.abs(answer)*.01);out.textContent=ok?'Верно! Теперь объясни в журнале, почему получается именно так.':'Пока не сходится. Проверь единицы и текущие условия; ниже доступен разбор.';out.dataset.correct=String(ok)});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);
new MutationObserver(()=>{if(host.hidden){stop();const url=new URL(location.href);if(url.searchParams.has('lab')){url.searchParams.delete('lab');history.replaceState(null,'',url.pathname+url.search+url.hash)}return}if(mounted)paint()}).observe(host,{attributes:true,attributeFilter:['hidden']});
window.matclubLab={refresh(){if(!mounted)mount();updateLink()},open(id){document.querySelector('[data-view="laboratory"]').click();open(id)},get state(){return{id:current.id,params:{...params},time,playing,baseline:baseline&&{...baseline},measurements:journal[current.id].length}},csv};
const link=new URLSearchParams(location.search).get('lab');if(M.labs.some(e=>e.id===link))window.matclubLab.open(link);
})();
